SELECT 'gongkao', '增长量计算', 'kp-xingce-data-growth-amount', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "增长量计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "反映数据增多或减少的绝对量数值。利用百化分化简除法是其核心。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "已知现期量和增长率，求比上年增加/减少了多少（具体数值带有单位）。这原本是全卷最恶心的算式。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "原始公式极其难算，我们必须借助百化分转化为极简公式："}]}, {"type": "katexBlock", "attrs": {"content": "原始公式: \\quad 增长量 = \\frac{现期量 \\times r}{1+r}"}}, {"type": "katexBlock", "attrs": {"content": "化简公式(若 r \\approx 1/n): \\quad 增量 = \\frac{现期量}{n+1}, \\quad 减量 = \\frac{现期量}{n-1}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出原始公式] --> B[将百分数 r 转化为分数 1/n]\nB --> C{看题干是增还是降?}\nC -- 增长 --> D[套用公式: 现期量 / (n+1)]\nC -- 下降 --> E[套用公式: 现期量 / (n-1)]\nD --> F[一步除法得出答案]\nE --> F"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年棉花产量 7240 吨，同比增长 14.2%。求增长了多少吨？选项：A. 815 B. 905 C. 1028 D. 1205"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求增长量，已知现期和 r。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "百化分转换：14.2% 极度接近 1/7，所以 n=7。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "判定符号：题目是“增长”，用加法，除数为 n+1 = 8。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：7240 ÷ 8 = 905。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死磕精确率导致无法转化：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果 r = 15%，找不到刚好相等的百化分怎么办？就近取 1/7(14.3%)，此时你的 n 取大了，算出来的结果会有微小偏差，去选项里找最接近的那一个即可，绝不能倒退回原始公式硬算！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把百化分表贴在桌子上，每天专门找 10 道增长量计算题，练习条件反射式的“n+1”或“n-1”法则。"}]}]}$$ AS jsonb), NULL, '增长量计算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "增长量计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_amount", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
